var USED_TEMPLATE_KEYS=new Set(),TEMPLATE_EN={},TEMPLATE_CONFLICTS={};
function G(key,english,vars){USED_TEMPLATE_KEYS.add(key);if(TEMPLATE_EN[key]!==undefined&&TEMPLATE_EN[key]!==english)TEMPLATE_CONFLICTS[key]=true;TEMPLATE_EN[key]=english;var text=TEXT.gen&&Object.prototype.hasOwnProperty.call(TEXT.gen,key)?TEXT.gen[key]:english;return vars?String(text).replace(/\{(\w+)\}/g,function(m,n){return Object.prototype.hasOwnProperty.call(vars,n)?String(vars[n]):m;}):text;}
function P(r,a){return a[r.int(0,a.length-1)];}
function sample(r,a,n){return r.shuffle(a).slice(0,n);}
function range(n){var out=[];for(var i=0;i<n;i+=1)out.push(i);return out;}
function uniqStrings(a){var seen=new Set();return a.filter(function(x){x=String(x);if(seen.has(x))return false;seen.add(x);return true;});}
function pickField(label,answer,wrongs,id,fallbacks){var pool=wrongs.map(String).filter(function(w){return w!==String(answer);});if(uniqStrings(pool).length<3&&fallbacks)pool=pool.concat(fallbacks.map(String).filter(function(w){return w!==String(answer);}));var f=candidate(String(answer),uniqStrings(pool).slice(0,5),label);if(id)f.id=id;return f;}
function intField(id,label,answer){return typed(id,label,answer,"integer");}
function hexField(id,label,answer){return typed(id,label,answer,"hex");}
function bytesField(id,label,answer){return typed(id,label,answer,"bytes");}
function LBL(key,english){return G("label."+key,english);}
function RES(){return t("fieldLabels.result","Result");}
function Q(titleKey,titleEn,vars,blocks,fields,explanation,meta){return{title:G("title."+titleKey,titleEn,vars),blocks:blocks,note:"",fields:fields,meta:meta||{},explanation:explanation||"",localized:true};}
function baseMeta(extra){var m={modelId:MODEL_ID,oracleVersion:ORACLE_VERSION};if(extra)Object.keys(extra).forEach(function(k){m[k]=extra[k];});return m;}
function yesNoText(b){return b?t("generated.choices.yes","Yes"):t("generated.choices.no","No");}

var NGEN={};
function scenario(id,level,r){r.level=0;if(!Object.prototype.hasOwnProperty.call(NGEN,id))return null;var g,tries=0;do{g=NGEN[id](level,r);}while(g.retry&&++tries<25);delete g.retry;return g;}

// ---------- Bit vectors ----------
function bitsOf(n,w){return(n>>>0).toString(2).padStart(w,"0").slice(-w);}
function popcount(n){var c=0;n>>>=0;while(n){c+=n&1;n>>>=1;}return c;}
function bitsField(id,label,answer){return typed(id,label,answer,"bits");}
function bitChoice(id,label,answer,extra){var opts=[["0","0"],["1","1"]].concat(extra||[]);return choice(id,label,String(answer),opts);}
function yn(id,label,b){return choice(id,label,b?"yes":"no",[["yes",yesNoText(true)],["no",yesNoText(false)]]);}
function toSigned(n,w){n&=(1<<w)-1;return n&(1<<(w-1))?n-(1<<w):n;}
// ---------- Gates ----------
var GATE_FN={AND:function(a){return a.every(function(x){return x===1;})?1:0;},OR:function(a){return a.some(function(x){return x===1;})?1:0;},XOR:function(a){return a.reduce(function(p,x){return p^x;},0);},NAND:function(a){return 1-GATE_FN.AND(a);},NOR:function(a){return 1-GATE_FN.OR(a);},XNOR:function(a){return 1-GATE_FN.XOR(a);},NOT:function(a){return 1-a[0];},BUF:function(a){return a[0];}};
// Four-state gate evaluation (0, 1, X; a Z input behaves as X), matching ideal Verilog primitive semantics.
function gate4(type,ins){var v=ins.map(function(x){return x==="Z"?"X":x;});var base=type.replace(/^N(?=AND|OR)/,"").replace(/^XN/,"X").replace("NOT","BUF"),inv=/^NAND|^NOR|^XNOR|^NOT/.test(type);var r;
  if(base==="AND")r=v.indexOf(0)>=0?0:v.indexOf("X")>=0?"X":1;else if(base==="OR")r=v.indexOf(1)>=0?1:v.indexOf("X")>=0?"X":0;else if(base==="XOR")r=v.indexOf("X")>=0?"X":v.reduce(function(p,x){return p^x;},0);else r=v[0];
  if(inv&&r!=="X")r=1-r;return r;}
// ---------- Expressions ----------
// AST: {v:"A"} | {not:e} | {and:[e..]} | {or:[e..]} | {xor:[e..]} | {k:0|1}
function V(n){return{v:n};}function NOT_(e){return{not:e};}function AND_(){return{and:Array.prototype.slice.call(arguments)};}function OR_(){return{or:Array.prototype.slice.call(arguments)};}function XOR_(){return{xor:Array.prototype.slice.call(arguments)};}
function evalE(e,env){if(e.v)return env[e.v];if(e.k!==undefined)return e.k;if(e.not)return 1-evalE(e.not,env);if(e.and)return e.and.every(function(x){return evalE(x,env)===1;})?1:0;if(e.or)return e.or.some(function(x){return evalE(x,env)===1;})?1:0;return e.xor.reduce(function(p,x){return p^evalE(x,env);},0);}
function prec(e){return e.or?1:e.xor?2:e.and?3:4;}
